p.product_status = 'ON_SALE'

    AND (p.product_name LIKE CONCAT('%', #{query.keyword}, '%')
         OR p.product_description LIKE CONCAT('%', #{query.keyword}, '%'))


    AND p.category_id = #{query.categoryId}


    AND p.product_price >= #{query.minPrice}


    AND p.product_price <= #{query.maxPrice}


    AND p.product_stock_quantity > 0
